@spec tv_freeze_group_spec  src=tests/specs/tv_freeze_group_spec.lua  loc=332  cases=8
@exercises dataStore (h.ds), trackerManager (h.tm), midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), groupManager (h.gm)
@surface   ds:assign, tm:rebuild, tm:addEvent, tm:flush, fm:dump, vm:setGridSize, ec:setPos, cmgr:invoke, gm:eachInstance, ds:get, gm:stateOf, tm:getChannel, tm:subscribe, gm:markGroup, tm:freezeRect, vm:freezeMode, vm:clearRegionAt, gm:newInstance, gm:assignEvent, gm:deleteInstance, ec:setSelection, vm:selectionAsRect
@harness   mk

# Intent
  Track B (fx freeze): the tv verb that converts a producer and mints a stock group over its
  own output. tm_fx_region_spec pins the conversion and the thin; this spec is the wiring --
  the gate, the mint, the one undo block they share, and what the mint leaves behind: an
  ordinary group, which instances, mirrors and deletes like any other.
  see design/archive/fx-freeze.md § Freeze to group

# Helpers
  @fn injectMixed(h, over)  @ 14-20
      -- A mixed chain over a note: the arp promotes derived notes, the sine leaves pb breakpoints,
      -- so the one fixture yields both member kinds without registering a stub generator.
  @fn addNote(h)  @ 22-26
  @fn fxColFor(h, chan)  @ 28-32
  @fn noteColIdx(h, chan)  @ 34-38
  @fn authoredUuid(h)  @ 40-42
  @fn authoredPitches(h)  @ 44-51
  @fn blockCounter(h)  @ 55-63
      -- util.atomic reads reaper.Undo_BeginBlock at call time, so a stub installed after the wrap still
      -- counts. Outermost blocks only: inner blocks collapse into the verb's.
  @fn frozen(harness)  @ 67-76
      -- The fixture frozen: producer converted, mint standing over its own output. Returns the
      -- harness and the instance the mint seated.
  @fn outputAt(h, lo)  @ 81-94
      -- The output standing in one region-length window, by offset from its start -- the shape a
      -- sibling instance has to reproduce. Says nothing about how many seats the thin left, which
      -- is tm_fx_region_spec's subject and free to move.
  @fn takeEvents(h)  @ 100-107
      -- The take keyed by uuid, so a comparison across an edit reads an event eaten rather than one
      -- merely moved -- the closing seat's whole hazard. Deliberately not filtered by gm membership:
      -- a seat left outside the rect is precisely the one a tile clears away, and filtering on
      -- stateOf would make the check blind to it.
  @fn pbUuidAt(h, ppq)  @ 109-113
  @fn noteUuidAt(h, ppq)  @ 115-119
  @fn pbColIdx(h, chan)  @ 121-125

# Cases
  @case 'freeze to group: the conversion mints one group over its own output'  [harness]  @ 130-167
  @case 'freeze to group: two rebuilds, one undo block'  [harness]  @ 174-193
  @case 'freeze to group: a colliding footprint declines before anything moves'  [harness]  @ 200-219
  @case 'freeze to group: a plain note at the caret is no producer'  [harness]  @ 223-237
  @case 'freeze to group: a sibling tiled directly below replays both member kinds'  [harness]  @ 245-261
  @case 'freeze to group: a mirror edit on either member kind reaches the sibling'  [harness]  @ 265-282
  @case 'freeze to group: deleting the group takes its output with it'  [harness]  @ 288-306
  @case 'freeze to group: a refused tile below the mint leaves it whole'  [harness]  @ 314-330

